from collections import deque

def transform(grid):
 H,W=len(grid),len(grid[0]); out=[row[:] for row in grid]
 seen=set(); comps=[]
 for r in range(H):
  for c in range(W):
   if grid[r][c]==1 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c));co=[]
    for x,y in q:
     co.append((x,y))
     for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
      nx,ny=x+dx,y+dy
      if 0<=nx<H and 0<=ny<W and grid[nx][ny]==1 and (nx,ny) not in seen:
       seen.add((nx,ny));q.append((nx,ny))
    comps.append(co)
 # exterior background 4 connectivity
 ext=set(); q=deque()
 for r in range(H):
  for c in range(W):
   if (r in (0,H-1) or c in (0,W-1)) and grid[r][c]==0 and (r,c) not in ext:
    ext.add((r,c));q.append((r,c))
 while q:
  x,y=q.popleft()
  for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
   nx,ny=x+dx,y+dy
   if 0<=nx<H and 0<=ny<W and grid[nx][ny]==0 and (nx,ny) not in ext:
    ext.add((nx,ny));q.append((nx,ny))
 for co in comps:
  degs=[]
  for x,y in co:
   deg=sum(0<=x+dx<H and 0<=y+dy<W and grid[x+dx][y+dy]==1 for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)))
   degs.append(deg)
  if not all(d==2 for d in degs): continue
  for x,y in co:
   for dx in (-1,0,1):
    for dy in (-1,0,1):
     nx,ny=x+dx,y+dy
     if 0<=nx<H and 0<=ny<W and grid[nx][ny]==0:
      out[nx][ny]=2 if (nx,ny) in ext else 3
 return out
